			}

		}

	}


	/**
	 * @inheritDoc
	 */
	public override function autoVisible (?value:Null<Bool>):GenericActuator<T> {

		if (value == null) {

			value = true;

		}

		_autoVisible = value;

		if (!value) {

			toggleVisible = false;

			if (setVisible) {

				setField (target, "visible", cacheVisible);

			}

		}

		return this;

	}


	/**
