				#elseif lime
				timeOffset += (System.getTimer () - pauseTime) / 1000;
				#elseif js
				timeOffset += (Browser.window.performance.now () - pauseTime) / 1000;
				#else
				timeOffset += (Timer.stamp () - pauseTime);
				#end
			#else
			timeOffset += (getTime() - pauseTime);
			#end

